test("addedRustSources returns only new Rust files under crate source trees", () => {
  let calledWith;
  const files = addedRustSources((args) => {
    calledWith = args;
    return [
      "crates/zeta/src/lib.rs",
      "crates/alpha/src/nested/module.rs",
      "crates/alpha/tests/integration.rs",
      "scripts/tool.mjs",
      "crates/alpha/src/nested/module.rs",
      "",
    ].join("\n");
  }, "origin/main");

  assert.deepEqual(calledWith, [
    "diff",
    "--diff-filter=A",
    "--name-only",
    "origin/main...HEAD",
    "--",
    "crates",
  ]);
  assert.deepEqual(files, [
    "crates/alpha/src/nested/module.rs",
    "crates/zeta/src/lib.rs",
  ]);
});

test("unboundSources names only added files with no artifact binding", () => {
  const files = [
    "crates/alpha/src/lib.rs",
    "crates/beta/src/lib.rs",
    "crates/gamma/src/lib.rs",
  ];
  const bound = new Set([
    "artifact:crates/alpha/src/lib.rs",
    "artifact:crates/gamma/src/lib.rs",
  ]);

  assert.deepEqual(unboundSources(files, bound), ["crates/beta/src/lib.rs"]);
});

test("goalArtifactBindings reads equivalent current and legacy bindings", () => {
  const current = new DatabaseSync(":memory:");
  const legacy = new DatabaseSync(":memory:");
  try {
    current.exec(
      "create table goal_artifacts (goal_id text, node_id text, mode text); insert into goal_artifacts values ('goal:delivery', 'artifact:crates/example/src/lib.rs', 'governed');",
    );
    legacy.exec(
      "create table goal_code (goal_id text, node_id text); insert into goal_code values ('goal:delivery', 'artifact:crates/example/src/lib.rs');",
    );

    assert.deepEqual(
      goalArtifactBindings(current).map((row) => ({ ...row })),
      [
        {
          goal_id: "goal:delivery",
          node_id: "artifact:crates/example/src/lib.rs",
          mode: "governed",
        },
      ],
    );
    assert.deepEqual(
      goalArtifactBindings(legacy).map((row) => ({ ...row })),
      [
        {
          goal_id: "goal:delivery",
          node_id: "artifact:crates/example/src/lib.rs",
          mode: "governed",
        },
      ],
    );
  } finally {
    current.close();
    legacy.close();
  }
});

test("goalArtifactBindings explains when the ledger has no binding table", () => {
  const db = new DatabaseSync(":memory:");
  try {
    assert.throws(
      () => goalArtifactBindings(db),
      /neither goal_artifacts nor legacy goal_code bindings/,
    );
  } finally {
    db.close();
  }
});

test("configuredRepositoryDb selects this repository when other ledgers exist", () => {
  const repositoryId = "9188c30bd2968f1b2aacd329e0d0a6af";
  const repositories = path.join("state", "repositories");
  const expected = path.join(repositories, repositoryId, "spec.db");
  let calledWith;

  const resolved = configuredRepositoryDb(
    (args) => {
      calledWith = args;
      return repositoryId;
    },
    (candidate) => candidate === expected,
    repositories,
  );

  assert.deepEqual(calledWith, [
    "config",
    "--local",
    "--get",
    "mindleak.repositoryId",
  ]);
  assert.equal(resolved, expected);
});
